import json
with open('/app/orders.json') as f:
    content = f.read()

# Parse multiple JSON objects from concatenated data
coder = json.JSONDecoder()
orders = []
pos = 0
while pos < len(content):
    # Skip whitespace
    while pos < len(content) and content[pos] in ' \t\n\r':
        pos += 1
    if pos >= len(content):
        break
    if content[pos] != '{':
        print(f"Unexpected char at pos {pos}: {content[pos]!r}")
        # Try to find next {
        pos = content.find('{', pos)
        if pos == -1:
            break
        continue
